CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), privy_user_id text NOT NULL UNIQUE, embedded_wallet_address text NOT NULL, access_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), circle_wallet_id text NOT NULL UNIQUE, chain_id integer NOT NULL, address text NOT NULL, user_id uuid REFERENCES users(id), assignment_status text NOT NULL DEFAULT 'available', operating_mode text NOT NULL DEFAULT 'frozen', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS trading_wallet_chain_address_uq ON trading_wallets(chain_id,address);
CREATE UNIQUE INDEX IF NOT EXISTS trading_wallet_user_uq ON trading_wallets(user_id) WHERE user_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS strategies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), trading_wallet_id uuid NOT NULL REFERENCES trading_wallets(id), current_version integer NOT NULL DEFAULT 1, state text NOT NULL DEFAULT 'DRAFT', authorization_epoch bigint NOT NULL DEFAULT 0, next_evaluation_at timestamptz, pause_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS strategy_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), strategy_id uuid NOT NULL REFERENCES strategies(id), version integer NOT NULL, original_instruction text NOT NULL, canonical_spec jsonb NOT NULL, spec_hash text NOT NULL, market_config_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(strategy_id,version));
CREATE TABLE IF NOT EXISTS authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purpose text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), nonce text NOT NULL UNIQUE, typed_message jsonb NOT NULL, signature text, message_hash text NOT NULL, challenge_expires_at timestamptz NOT NULL, mandate_expires_at timestamptz NOT NULL, consumed_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment text NOT NULL, provider text NOT NULL, provenance jsonb NOT NULL, normalized_metrics jsonb NOT NULL, payload_hash text NOT NULL, quality_verdict text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), strategy_id uuid NOT NULL REFERENCES strategies(id), observation_id uuid REFERENCES market_observations(id), evaluator_version text NOT NULL, result text NOT NULL, reasons jsonb NOT NULL, proposed_action jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), decision_id uuid NOT NULL REFERENCES decisions(id), wallet_id uuid NOT NULL REFERENCES trading_wallets(id), state text NOT NULL, economic_action_key text NOT NULL UNIQUE, provider_idempotency_key text NOT NULL UNIQUE, quote jsonb NOT NULL, actual_input_atomic text, actual_output_atomic text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS budget_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES trading_wallets(id), execution_id uuid NOT NULL UNIQUE REFERENCES executions(id), utc_day text NOT NULL, reserved_notional_atomic text NOT NULL, state text NOT NULL DEFAULT 'reserved', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS funding_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), source_address text NOT NULL, destination_address text NOT NULL, chain_id integer NOT NULL, token_address text NOT NULL, amount_atomic text NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', receipt_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, payload jsonb NOT NULL, dedupe_key text NOT NULL UNIQUE, scheduled_at timestamptz NOT NULL, lease_owner text, lease_expires_at timestamptz, fencing_token bigint NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, terminal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor text NOT NULL, user_id uuid REFERENCES users(id), action text NOT NULL, target text NOT NULL, correlation_id text NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
